    id: 'uruguay',
    name: 'Uruguay',
    flag: '🇺🇾',
    lawName: 'Personal Data Protection Law No. 18,331',
    authority: 'Regulatory and Control Unit of Personal Data (URCDP)',
    region: 'Americas',
